package hotel.user;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A user account as it is stored in the database (table "app_user", because "user" is a reserved word). */
@Entity
@Table(name = "app_user")
public class UserEntity {

    /** Generated by the database. */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long userId;

    @Column(nullable = false, unique = true)
    private String username;

    /** BCrypt hash, never the plain password. */
    @Column(nullable = false)
    private String passwordHash;

    /** Stored as text ("ADMIN", "CUSTOMER", "RECEPTIONIST"), not as a number. */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private Role role;

    /** Needed by JPA. */
    protected UserEntity() {
    }

    public UserEntity(String username, String passwordHash, Role role) {
        this.username = username;
        this.passwordHash = passwordHash;
        this.role = role;
    }

    public Long getUserId() {
        return userId;
    }

    public String getUsername() {
        return username;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public Role getRole() {
        return role;
    }
}
